using System.IO;
using System.Security.Cryptography;
using System.Text.Json;
using System.Windows;
using System.Windows.Automation.Peers;
using System.Windows.Automation.Provider;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Interop;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using Pausewell.ComponentLab;
using Pausewell.Controls;
namespace Pausewell.MaterialLab;
public static class MaterialVerification
{
 private static IEnumerable<T> Descendants<T>(DependencyObject root)where T:DependencyObject{for(var i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var child=VisualTreeHelper.GetChild(root,i);if(child is T t)yield return t;foreach(var nested in Descendants<T>(child))yield return nested;}}
 private static void Invoke(Button b)=>((IInvokeProvider)UIElementAutomationPeer.CreatePeerForElement(b)!.GetPattern(PatternInterface.Invoke)).Invoke();
 private static string RegionHash(string file,FrameworkElement target,FrameworkElement root){var b=new BitmapImage();b.BeginInit();b.CacheOption=BitmapCacheOption.OnLoad;b.UriSource=new Uri(file);b.EndInit();var scale=VisualTreeHelper.GetDpi(root).DpiScaleX;var p=target.TranslatePoint(new Point(16,2),root);var crop=new CroppedBitmap(b,new Int32Rect((int)(p.X*scale),(int)(p.Y*scale),(int)((target.ActualWidth-32)*scale),(int)(4*scale)));var bytes=new byte[crop.PixelHeight*crop.PixelWidth*4];crop.CopyPixels(bytes,crop.PixelWidth*4,0);return Convert.ToHexString(SHA256.HashData(bytes));}
 private static double Luminance(Color c){double Linear(byte v){var n=v/255d;return n<=.04045?n/12.92:Math.Pow((n+.055)/1.055,2.4);}return .2126*Linear(c.R)+.7152*Linear(c.G)+.0722*Linear(c.B);}
 private static double SurfaceContrast(string file,FrameworkElement target,FrameworkElement root){var bitmap=new BitmapImage(new Uri(file));var b=new FormatConvertedBitmap(bitmap,PixelFormats.Bgra32,null,0);var scale=VisualTreeHelper.GetDpi(root).DpiScaleX;var p=target.TranslatePoint(new Point(24,12),root);var crop=new CroppedBitmap(b,new Int32Rect((int)(p.X*scale),(int)(p.Y*scale),(int)((target.ActualWidth-48)*scale),Math.Max(1,(int)(2*scale))));var pixels=new byte[crop.PixelWidth*crop.PixelHeight*4];crop.CopyPixels(pixels,crop.PixelWidth*4,0);var ink=Luminance(DesignTheme.Brush("#292824").Color);var min=double.MaxValue;for(var i=0;i<pixels.Length;i+=4)min=Math.Min(min,(Luminance(Color.FromRgb(pixels[i+2],pixels[i+1],pixels[i]))+.05)/(ink+.05));return min;}
 public static async Task Run(MaterialWindow w,string directory)
 {
  Directory.CreateDirectory(directory);var started=DateTimeOffset.Now;var checks=new List<object>();var frames=new List<object>();var success=true;var original=NativeInput.CursorPosition;
  void Verify(string name,bool pass,object? detail=null){checks.Add(new{name,passed=pass,detail});if(!pass)throw new InvalidOperationException(name);}
  string Shot(string name){var file=Path.Combine(directory,name+".png");NativeCapture.Save((FrameworkElement)w.Content,file);var root=(FrameworkElement)w.Content;object Bounds(FrameworkElement e){var p=e.TranslatePoint(new Point(0,0),root);return new{x=p.X,y=p.Y,width=e.ActualWidth,height=e.ActualHeight};}frames.Add(new{name,scale=VisualTreeHelper.GetDpi(root).DpiScaleX,stage=Bounds(w.Stage),navigation=Bounds(w.Navigation),dialog=w.ModalLayer.IsVisible?Bounds(w.Dialog):null});return file;}
  try{
   await Task.Delay(350);Verify("材质样板不引用业务与数据库",!typeof(MaterialWindow).Assembly.GetReferencedAssemblies().Any(a=>a.Name is "Pausewell.Core" or "Pausewell.Storage"));Verify("窗口可接收仅限自身的测试输入",NativeInput.Activate(w));await Task.Delay(80);w.ApplyState();
   Verify("参数读取既有规范与独立材质调校值",w.Profiles["navigation"].Tint==.48&&w.Profiles["navigation"].Blur==24&&w.Profiles["popup"].Tint==.62&&w.Profiles["popup"].Blur==28);
   Verify("导航和内容使用独立下层背景",ReferenceEquals(w.Navigation.BackdropSource,w.Ambient)&&ReferenceEquals(w.ContentSurface.BackdropSource,w.Ambient));Verify("任务层采样完整基础场景且不循环引用",ReferenceEquals(w.Dialog.BackdropSource,w.BaseScene)&&!Descendants<GlassSurface>(w.BaseScene).Contains(w.Dialog));
   Verify("正文树没有模糊效果",Descendants<FrameworkElement>(w.ContentSurface.ContentHost).All(x=>x.Effect is not System.Windows.Media.Effects.BlurEffect));Verify("阅读层不执行模糊",!w.ContentSurface.UsesBlur);Verify("导航与任务层按能力启用模糊",w.Navigation.UsesBlur==!w.EffectiveReduced&&w.Dialog.UsesBlur==!w.EffectiveReduced,new{w.EffectiveReduced,tier=RenderCapability.Tier>>16});
   var origin=w.Navigation.TranslatePoint(new Point(0,0),w.Ambient);Verify("导航采样位置对应自身且包含过采样边缘",Math.Abs(w.Navigation.SampleBounds.X-(origin.X-32))<1&&Math.Abs(w.Navigation.SampleBounds.Width-(w.Navigation.ActualWidth+64))<1,new{origin,sample=w.Navigation.SampleBounds});
   var warm=Shot("01-warm-home");var initialHash=RegionHash(warm,w.Navigation,(FrameworkElement)w.Content);var navContrast=SurfaceContrast(warm,w.Navigation,(FrameworkElement)w.Content);Verify("导航合成背景对正文色达到 4.5 比 1",navContrast>=4.5,new{minimumSampleContrast=navContrast});
   w.LightChoice.Value=.90;await Task.Delay(180);var moved=Shot("02-light-moved");Verify("移动环境光改变导航合成像素",initialHash!=RegionHash(moved,w.Navigation,(FrameworkElement)w.Content));w.LightChoice.Value=.36;
   for(var i=1;i<3;i++){w.EnvironmentChoice.SelectedIndex=i;await Task.Delay(150);Shot(i==1?"03-light-home":"04-contrast-home");}Verify("三种环境切换保留导航",w.Ambient.Mode==2&&w.SelectedNavigation==0);w.EnvironmentChoice.SelectedIndex=0;
   foreach(var id in DesignTheme.Ids){w.ThemeChoice.SelectedIndex=Array.IndexOf(DesignTheme.Ids,id);await Task.Delay(100);Verify("主题选择与环境同步 "+id,DesignTheme.Current==id&&w.Ambient.Environment==((SolidColorBrush)w.Palette["Theme.ambient"]).Color);var ratio=1.05/(Luminance(((SolidColorBrush)w.Palette["Theme.primary"]).Color)+.05);Verify("主题主按钮白字达到 4.5 比 1 "+id,ratio>=4.5,new{contrast=ratio});Shot("05-theme-"+id);}w.ThemeChoice.SelectedIndex=0;
   w.ReducedChoice.IsChecked=true;await Task.Delay(140);Verify("减少透明度移除所有背景模糊",w.EffectiveReduced&&!w.Navigation.UsesBlur&&!w.Dialog.UsesBlur);Shot("06-solid-home");w.ReducedChoice.IsChecked=false;w.InactiveChoice.IsChecked=true;await Task.Delay(100);Verify("失焦模拟应用到所有层",w.Navigation.Inactive&&w.ContentSurface.Inactive&&w.Dialog.Inactive);Shot("07-inactive-home");w.InactiveChoice.IsChecked=false;
   w.PreviewButton.Focus();Invoke(w.PreviewButton);await Task.Delay(600);NativeInput.Activate(w);await Task.Delay(100);Verify("真实预览进入模态与禁用背景",w.ModalLayer.IsVisible&&!w.BaseScene.IsEnabled&&!w.EnvironmentChoice.IsEnabled);Verify("弹窗首次聚焦主动作",Keyboard.FocusedElement==w.ConfirmButton,new{dialogWidth=w.Dialog.ActualWidth,dialogHeight=w.Dialog.ActualHeight,stageWidth=w.Stage.ActualWidth,stageHeight=w.Stage.ActualHeight,modalWidth=w.ModalLayer.ActualWidth,modalHeight=w.ModalLayer.ActualHeight});Verify("弹窗保持清晰文字且背景独立模糊",Descendants<TextBlock>(w.Dialog.ContentHost).All(x=>x.Effect==null));Shot("08-reminder-warm");
   NativeInput.Key(0x09);await Task.Delay(60);Verify("Tab 在弹窗进入延期动作",Keyboard.FocusedElement==w.DeferButton);NativeInput.Key(0x09);await Task.Delay(60);NativeInput.Key(0x09);await Task.Delay(60);Verify("Tab 不越出弹窗",Keyboard.FocusedElement==w.ConfirmButton);
   Invoke(w.ConfirmButton);await Task.Delay(100);Verify("确认只修改样板计数并返回原焦点",!w.ModalLayer.IsVisible&&w.PreviewConfirmCount==1&&w.BaseScene.IsEnabled&&Keyboard.FocusedElement==w.PreviewButton);
   Invoke(w.PreviewButton);await Task.Delay(80);Invoke(w.DeferButton);await Task.Delay(80);Verify("延期不计完成",w.PreviewDeferCount==1&&w.PreviewConfirmCount==1&&!w.ModalLayer.IsVisible);
   Invoke(w.PreviewButton);await Task.Delay(80);NativeInput.Key(0x1B);await Task.Delay(80);Verify("Esc 退出预览不记录完成",!w.ModalLayer.IsVisible&&w.PreviewConfirmCount==1);
   foreach(var mode in new[]{1,2}){w.EnvironmentChoice.SelectedIndex=mode;await Task.Delay(80);w.ShowPreview();await Task.Delay(130);Shot(mode==1?"09-reminder-light":"10-reminder-contrast");w.ClosePreview("材质检查完成。");}
   w.EnvironmentChoice.SelectedIndex=2;w.ShowPreview(true);await Task.Delay(250);var transmission=Shot("14-transmission-contrast");Verify("透射对照隐藏阅读面但保留真实背景",w.ContentSurface.Visibility==Visibility.Hidden&&w.Dialog.IsVisible);var taskContrast=SurfaceContrast(transmission,w.Dialog,(FrameworkElement)w.Content);Verify("对比环境任务层正文保持 4.5 比 1",taskContrast>=4.5,new{minimumSampleContrast=taskContrast});w.ClosePreview("透射对照结束。");Verify("退出对照恢复阅读面",w.ContentSurface.Visibility==Visibility.Visible);
   w.EnvironmentChoice.SelectedIndex=0;w.ReducedChoice.IsChecked=true;w.ShowPreview();await Task.Delay(120);Shot("11-reminder-solid");Verify("实色弹窗仍可完成",w.ConfirmButton.IsVisible&&!w.Dialog.UsesBlur);w.ClosePreview("实色预览结束。");w.ReducedChoice.IsChecked=false;
   w.Width=900;w.Height=650;await Task.Delay(160);Shot("12-compact-home");Verify("紧凑窗口导航与预览入口保持可见",w.Navigation.IsVisible&&w.PreviewButton.IsVisible&&w.Navigation.ActualWidth<=w.Stage.ActualWidth);w.ShowPreview();await Task.Delay(130);Shot("13-compact-reminder");var buttonBottom=w.ConfirmButton.TranslatePoint(new Point(0,w.ConfirmButton.ActualHeight),w.Stage).Y;Verify("紧凑弹窗主动作未超出场景",buttonBottom>0&&buttonBottom<=w.Stage.ActualHeight);w.ClosePreview("紧凑检查结束。");w.Width=1200;w.Height=940;await Task.Delay(200);var renders=w.Ambient.RenderCount;var samples=w.Navigation.SampleUpdates;await Task.Delay(600);Verify("静止期间未主动重绘背景或重设采样",w.Ambient.RenderCount==renders&&w.Navigation.SampleUpdates==samples);
  }catch(Exception ex){success=false;checks.Add(new{name="异常",passed=false,error=ex.ToString()});}
  finally{NativeInput.Up();NativeInput.Move(original);using var process=System.Diagnostics.Process.GetCurrentProcess();File.WriteAllText(Path.Combine(directory,"material-test-results.json"),JsonSerializer.Serialize(new{success,startedAt=started,finishedAt=DateTimeOffset.Now,dpi=NativeInput.GetDpiForWindow(new WindowInteropHelper(w).Handle),renderTier=RenderCapability.Tier>>16,workingSetBytes=process.WorkingSet64,privateBytes=process.PrivateMemorySize64,checks,frames,scope="Material lab only. Native UI; sampled background contrast, not full accessibility or GPU benchmark. No production reminders, no realtime refraction, no long-run or all-device acceptance."},new JsonSerializerOptions{WriteIndented=true}));Application.Current.Shutdown(success?0:1);}
 }
}
